import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {connectClient, startEngine, stopEngines} from './wsTestSupport.js';

afterEach(stopEngines);

describe('specs/hal-engine-conversation-list/spec.md#43', () => {
  it('returns the connected user’s page even when the frame names another user', async () => {
    const store = new InMemorySessionStore();
    store.create('own', 'u1');
    store.create('foreign', 'u2');
    const [own] = store.listFor('u1');
    const url = await startEngine(store);
    const client = connectClient(url);
    const frames: unknown[] = [];
    await new Promise<void>(resolve => {
      client.on('message', raw => {
        const frame = JSON.parse(String(raw)) as {type: string};
        if (frame.type === 'connected') {
          client.send(JSON.stringify({
            type: 'list_sessions', userId: 'u2', limit: 1,
            before: {updatedAt: own.updatedAt.toISOString(), sessionId: 'ownz'},
          }));
          client.send(JSON.stringify({type: 'ping', timestamp: 1}));
          return;
        }
        if (frame.type === 'pong') return resolve();
        frames.push(frame);
      });
    });
    expect(frames).toEqual([{
      type: 'session_list',
      sessions: [{sessionId: 'own', createdAt: own.createdAt.toISOString(), updatedAt: own.updatedAt.toISOString(), entryCount: 0}],
    }]);
  });
});
EOF
